from pathlib import Path
import json,subprocess

tid='DEV-PRED-AUTOBUILD-PINFIX-20260930-E005'
source='57d1aa8b59a31b8b776b264aa3ac663ebc0277c1'
mirror=Path.home()/'.local/share/prediction-project-executor/repo'
wtroot=Path.home()/'.local/share/prediction-project-executor/worktrees'
state=Path.home()/'.local/state/prediction-project-executor'/(tid+'.json')
branch='ai/'+tid

def run(args,cwd):
    cp=subprocess.run(['git',*args],cwd=cwd,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
    return cp.returncode,cp.stdout

code='6000000000000000000000000000000000000009'
if not mirror.is_dir():
    code='6000000000000000000000000000000000000001'
else:
    rc,_=run(['rev-parse',source+'^{commit}'],mirror)
    if rc!=0:
        code='6000000000000000000000000000000000000002'
    else:
        rc,b=run(['branch','--list',branch],mirror)
        branch_exists=(rc==0 and bool(b.strip()))
        wt=(wtroot/tid)
        regroot=mirror/'.git/worktrees'
        stale_reg=False
        if regroot.is_dir():
            for p in regroot.iterdir():
                try:
                    gd=(p/'gitdir').read_text(errors='replace') if (p/'gitdir').is_file() else ''
                except Exception:
                    gd=''
                if tid in gd or tid in p.name:
                    stale_reg=True
        claimed=False
        if state.is_file():
            try:
                obj=json.loads(state.read_text())
                claimed=(obj.get('status')=='CLAIMED' and obj.get('source_commit')==source)
            except Exception:
                pass
        if wt.exists():
            code='6000000000000000000000000000000000000003'
        elif branch_exists and stale_reg:
            code='6000000000000000000000000000000000000004'
        elif branch_exists:
            code='6000000000000000000000000000000000000005'
        elif stale_reg:
            code='6000000000000000000000000000000000000006'
        elif not claimed:
            code='6000000000000000000000000000000000000007'
        else:
            code='6000000000000000000000000000000000000008'
print(code)
